    e.innerHTML=`<div class="cmw-card cmw-plan-workspace"><div class="cmw-section-head"><div><span>GOVERNED MISSION PLAN</span><h3>${esc(plan?.id?`MP-${plan.id}`:"No plan yet")}</h3><p>${esc(plan?.plan?.objective||contract.objective||"The system will build a plan from the current mission truth and governed contracts.")}</p></div><span class="cmw-plan-state">${esc(status)}</span></div><div class="cmw-grid cmw-facts">${fact("Sector",contract.sectorCode||"—")}${fact("Country",contract.countryCode||"—")}${fact("Contract",sector.scenarioCode||"General")}${fact("Contract valid",validation.valid===false?"NO":"YES")}${fact("Evaluation",es)}${fact("Expires",evaluation?.expiresAt||plan?.expiresAt||"—")}</div><div class="cmw-plan-checks"><article><b>Truth & context</b><span>${evaluation?.evidence?.truthFresh===false?"STALE":"CURRENT"}</span></article><article><b>Resources</b><span>${evaluation?.evidence?.resourcesReady===false?"BLOCKED":"CHECKED"}</span></article><article><b>Assignment</b><span>${evaluation?.evidence?.assignmentFeasible===false?"BLOCKED":"CHECKED"}</span></article><article><b>Authorization readiness</b><span>${evaluation?.evidence?.authorizationReady===false?"BLOCKED":"CHECKED"}</span></article><article><b>Recovery path</b><span>${evaluation?.evidence?.recoveryReady===false?"MISSING":"READY"}</span></article></div>${steps.length?`<div class="cmw-plan-steps"><h4>RECOMMENDED PATH</h4>${steps.map((x,i)=>`<article><span>${i+1}</span><div><b>${esc(x.label||x.actionCode||x.code||"Step")}</b><p>${esc(x.reason||x.description||"")}</p></div></article>`).join("")}</div>`:""}${findings.length?`<div class="cmw-plan-findings"><h4>EVALUATION FINDINGS</h4>${findings.map(x=>`<article><b>${esc(x.code||x.type||"Finding")}</b><p>${esc(x.message||x.reason||String(x))}</p></article>`).join("")}</div>`:""}<div class="cmw-plan-actions">${!plan?`<button type="button" class="cmw-primary" data-plan-generate>GENERATE PLAN</button>`:""}${plan&&es==="NOT_EVALUATED"?`<button type="button" class="cmw-primary" data-plan-evaluate>EVALUATE PLAN</button>`:""}${plan&&es!=="ACCEPTABLE"&&es!=="NOT_EVALUATED"?`<button type="button" class="cmw-secondary" data-plan-evaluate>RE-EVALUATE</button>`:""}${plan&&es==="ACCEPTABLE"&&status==="PROPOSED"?`<button type="button" class="cmw-primary" data-plan-accept>ACCEPT PLAN</button>`:""}${status==="ACCEPTED"?`<button type="button" class="cmw-secondary" data-plan-execution>OPEN EXECUTION →</button>`:""}</div><div class="cmw-plan-explain"><b>Safety boundary</b><p>Planning never executes. Acceptance does not bypass authorization. Execution requires the accepted plan, fresh mission truth, canonical action authorization, assignment and verification.</p></div>${nextSituation?`<div class="cmw-next-situation"><span>NEXT SITUATION</span><b>${esc(nextSituation.state||nextSituation.status||"READY")}</b><p>${esc(nextSituation.summary||nextSituation.reason||"")}</p></div>`:""}</div>`;
    q("[data-plan-generate]")?.addEventListener("click",async()=>{await planRequest(`/api/mission-execution/missions/${id}/plan`,"POST",{});});
    q("[data-plan-evaluate]")?.addEventListener("click",async()=>{if(!state.plan?.id)return;await planRequest(`/api/mission-execution/missions/${id}/plan/${state.plan.id}/evaluate`,"POST",{});});
