  function renderActionContext(code){const e=q("#cmwActionContext"),a=actionByCode(code);if(!e||!a)return;const c=normalizeActionId(code);if(c==="request_foryou_mission")return renderForYouRequest(e,a);if(c==="cancel_foryou_request")return renderCancelForYouRequest(e,a);if(c==="message")return renderMessage(e);if(c==="assign_driver")return renderAssignment(e,a.label==="Change Executor");if(["share_foryou","share_network"].includes(c))return renderShareChooser(e);if(["review_network","review_foryou","accept_network","reject_network","approve_foryou_request","decline_foryou_request"].includes(c))return renderReview(e,c);if(c==="edit_mission")return renderEdit(e);if(c==="edit_mission_data")return renderEdit(e);if(c==="cancel_mission")return renderCancel(e);if(c==="delete_mission")return renderDelete(e);if(c==="advance_execution")return renderAdvanceExecution(e,a);if(c==="capture_delivery_proof")return renderProof(e);if(c==="report_exception")return renderException(e);if(c==="review_completion_blocker")return renderCompletionBlocker(e);if(c==="navigate")return renderNavigate(e,a);if(["start_custody_resolution","start_custody_recovery","confirm_custody_release","finalize_custody_transfer","accept_custody","reassign_custody_receiver","abort_custody_transfer"].includes(c))return renderCustody(e,c);if(c==="reclaim_execution")return renderReclaim(e,a);e.innerHTML=`<div class="cmw-context"><span>SELECTED ACTION</span><h3>${esc(a.label||c)}</h3><p>${esc(a.reason||"")}</p><button type="button" class="cmw-primary" id="cmwRunAction">CONTINUE</button></div>`;q("#cmwRunAction")?.addEventListener("click",()=>runSecured(a));}
