  async function renderAssignment(e,changing=false){e.innerHTML=`<div class="cmw-context"><span>ASSIGNMENT</span><h3>${changing?"Change Executor":"Assign Executor"}</h3><p>${changing?"Choose the new executor for this mission.":"Choose who will execute this mission."}</p><input id="cmwExecutorSearch" autocomplete="off" placeholder="Search people"><div id="cmwExecutors">Loading…</div><button type="button" class="cmw-primary" id="cmwAssign" disabled>CONFIRM</button></div>`;try{const d=await api("/api/drivers"),rows=(d?.drivers||[]).filter(x=>Number(x.active??1)===1),draw=()=>{const term=String(q("#cmwExecutorSearch")?.value||"").toLowerCase();q("#cmwExecutors").innerHTML=rows.filter(x=>!term||String(x.name||"").toLowerCase().includes(term)).map(x=>`<button type="button" class="cmw-person" data-executor="${Number(x.id)}"><b>${esc(x.name||`Executor ${x.id}`)}</b><small>${esc(x.situation||"Available")}</small></button>`).join("")||"<p>No active executor matches.</p>";qa("[data-executor]").forEach(b=>b.onclick=()=>{q("#cmwAssign").dataset.driver=b.dataset.executor;q("#cmwAssign").disabled=false;});};q("#cmwExecutorSearch").oninput=draw;draw();q("#cmwAssign").onclick=async()=>{const driverId=Number(q("#cmwAssign").dataset.driver||0);if(!driverId)return;try{await runSecured(actionByCode("assign_driver"),{driverId});feedback(changing?"Executor changed.":"Executor assigned.");showView("execution",false);}catch(err){feedback(err?.message||"Assignment failed.",true);}};}catch(err){feedback(err?.message||"Executors are unavailable.",true);}}
  function renderShareChooser(e){const options=actionList().filter(a=>["share_foryou","share_network"].includes(normalizeActionId(a.code)));const activeCustody=["PickedUp","InTransit"].includes(String(state.truth?.lifecycle?.status||state.mission?.status||""));e.innerHTML=`<div class="cmw-context"><span>SHARING</span><h3>Share mission</h3><p>${activeCustody?"Choose a handoff route for this mission.":"Choose how you want to share this mission."}</p><div class="cmw-choice-grid">${options.map(a=>`<button type="button" class="cmw-choice" data-share-code="${esc(a.code)}"><b>${a.code==="share_foryou"?"ForYou":"Trusted Network"}</b><small>${esc(a.reason||"")}</small></button>`).join("")}</div></div>`;qa("[data-share-code]").forEach(b=>b.onclick=()=>renderShareForm(e,b.dataset.shareCode,activeCustody));}
